// App.js
import React from 'react';
import ReactDOM from 'react-dom';
import 'carbon-components/css/carbon-components.min.css';
import { Dropdown } from 'carbon-components-react';

const items = [
  { id: 'option-1', label: 'Option 1', value: '1' },
  { id: 'option-2', label: 'Option 2', value: '2' },
  { id: 'option-3', label: 'Option 3', value: '3' },
];

function App() {
  return (
    <div style={{ width: 300, margin: '2rem' }}>
      <h1>Welcome to React, with Carbon Examples!</h1>
      <p>This is not a dropdown title.</p>
      <p>This is not some helper text.</p>
      <Dropdown
        id="carbon-dropdown-example"
        titleText="This is not a dropdown title."
        helperText="This is not some helper text."
        label="Dropdown menu options"
        items={items}
        itemToString={item => item.label}
      />
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));

// After starting the app, open your browser dev tools + Axe or DAP plugin
// and inspect the closed-dropdown markup to see the two violations.
